import("./src/inventory.js").then(({ Inventory }) => {
  const inv = new Inventory();
  // R1: release normalizes sku
  inv.add(" ab-1 ", 5);
  inv.reserve("AB-1", 2);
  inv.release("  ab-1 ", 2);
  console.assert(inv.snapshot()[0].reserved === 0, "release normalization failed");
  // R1: non-string / empty sku -> TypeError
  for (const bad of [null, 42, "  "]) {
    try { inv.release(bad, 1); console.assert(false, "expected TypeError"); }
    catch (e) { console.assert(e instanceof TypeError, "wrong error for sku " + JSON.stringify(bad)); }
  }
  // R2: quantities
  for (const bad of [0, -3, 1.5, "2", NaN]) {
    try { inv.add("X", bad); console.assert(false, "expected RangeError"); }
    catch (e) { console.assert(e instanceof RangeError, "wrong error for qty " + bad); }
  }
  // R4: reserve unknown / too much
  try { inv.reserve("NOPE", 1); console.assert(false); } catch (e) { console.assert(e instanceof RangeError); }
  // R5: release too much -> no change
  const before = JSON.stringify(inv.snapshot());
  try { inv.release("ab-1", 1); console.assert(false); } catch (e) { console.assert(e instanceof RangeError); }
  console.assert(JSON.stringify(inv.snapshot()) === before, "release changed state on error");
  // R6: remove cannot drop below reserved
  inv.add("AB-1", 4); // onHand 9, reserved 0
  inv.reserve("AB-1", 3);
  const before2 = JSON.stringify(inv.snapshot());
  try { inv.remove("AB-1", 7); console.assert(false); } catch (e) { console.assert(e instanceof RangeError); }
  console.assert(JSON.stringify(inv.snapshot()) === before2, "remove changed state on error");
  inv.remove("AB-1", 6); // ok: 9-6=3 == reserved
  console.assert(inv.snapshot()[0].onHand === 3 && inv.snapshot()[0].available === 0, "remove math wrong");
  // R7: code-unit order
  const inv2 = new Inventory();
  inv2.add("b", 1); inv2.add("A-B", 1); inv2.add("a1", 1); inv2.add("A1", 1); inv2.add("ab", 1);
  const skus = inv2.snapshot().map(s => s.sku);
  console.assert(JSON.stringify(skus) === JSON.stringify(["A-B","A1","ab","a1","b"]), "sort wrong: " + skus);
  console.log("extra checks passed");
});
'

