import("./src/inventory.js").then(({ Inventory }) => {
  const inv2 = new Inventory();
  for (const s of ["b", "A-B", "a1", "A1", "ab"]) inv2.add(s, 1);
  const skus = inv2.snapshot().map(s => s.sku);
  console.assert(JSON.stringify(skus) === JSON.stringify(["A-B", "A1", "AB", "B"]), "sort wrong: " + skus);
  // R7: SKUs with nothing on hand and nothing reserved are left out
  const inv3 = new Inventory();
  inv3.add("X", 2);
  inv3.remove("X", 2);
  console.assert(inv3.snapshot().length === 0, "empty sku not filtered");
  console.log("all extra checks passed");
});
